    var M = {"john":{"it":"«Yahweh è misericordioso»"},"mary":{"it":"Incerto — «amata», «amarezza» o «figlia desiderata»"},"muhammad":{"it":"«Il lodato», «degno di lode»"},"alexander":{"it":"«Difensore degli uomini» (aléxō «difendere» + anḗr «uomo»)"},"joseph":{"it":"«Egli aggiungerà» / «che Dio aggiunga»"},"michael":{"it":"«Chi è come Dio?»"},"george":{"it":"«Agricoltore, lavoratore della terra» (gē «terra» + ergon «lavoro»)"},"sophia":{"it":"«Saggezza»"},"fatima":{"it":"«Colei che svezza / si astiene» (radice f-ṭ-m)"},"ali":{"it":"«Alto, elevato, sublime» (radice ʿ-l-w)"},"krishna":{"it":"«Scuro, nero» (dal colorito blu-nerastro della divinità)"},"rama":{"it":"«Piacevole, affascinante, delizioso» (radice ram- «piacere, dilettare»)"},"david":{"it":"«Amato»"},"daniel":{"it":"«Dio è il mio giudice» (dān «giudicare» + ʼēl «Dio»)"},"peter":{"it":"«Roccia, pietra» — coniato da Gesù per rendere l’aramaico Kēfā"},"paul":{"it":"«Piccolo, umile»"},"thomas":{"it":"«Gemello»"},"abraham":{"it":"«Padre di molte nazioni»"},"isaac":{"it":"«Egli ride» / «egli riderà»"},"jacob":{"it":"«Soppiantatore», «colui che tiene il calcagno»"},"moses":{"it":"«Tratto dalle acque» (tradizionale)"},"solomon":{"it":"«Pace» (da shalom)"},"matthew":{"it":"«Dono di Yahweh»"},"adam":{"it":"«Uomo; umanità», da adamah «terra, suolo»"},"noah":{"it":"«Riposo, conforto»"},"gabriel":{"it":"«Dio è la mia forza»"},"elijah":{"it":"«Il mio Dio è Yahweh»"},"sarah":{"it":"«Principessa, nobildonna»"},"anna":{"it":"«Grazia, favore»"},"elizabeth":{"it":"«Il mio Dio è un giuramento»"},"omar":{"it":"«Longevo, fiorente, prospero»"},"aisha":{"it":"«Vivente, viva, prospera»"},"khadija":{"it":"«Nata prematuramente, bambina prematura»"},"abdullah":{"it":"«Servo di Dio»"},"hassan":{"it":"\"Buono, bello, avvenente\""},"husayn":{"it":"\"Piccolo Hasan\", \"il piccolo bello\""},"zaynab":{"it":"Una pianta del deserto profumata e fiorita"},"nicholas":{"it":"\"Vittoria del popolo\""},"helen":{"it":"Incerto — probabilmente \"torcia, la splendente\""},"catherine":{"it":"Incerto — collegato per etimologia popolare a \"puro\""},"margaret":{"it":"\"Perla\""},"philip":{"it":"\"Amante dei cavalli\""},"theodore":{"it":"\"Dono di Dio\""},"anthony":{"it":"Un nome gentilizio romano di origine incerta, forse etrusca"},"julia":{"it":"\"Giovane\"; forma femminile del nome gentilizio Iulius, legata a Giove"},"lakshmi":{"it":"\"Segno, marchio\" → \"buona sorte, prosperità\""},"arjun":{"it":"\"Luminoso, bianco, argenteo, chiaro\""},"sita":{"it":"\"Solco\" (la linea tracciata dallʼaratro)"},"ganesh":{"it":"\"Signore dei gana (schiere, moltitudini)\""},"priya":{"it":"\"Amata, cara\""}};
    var B = {"john":{"it":"Uno dei nomi più diffusi sulla Terra. L’ebraico Yōḥānān, portato da John the Baptist e John the Apostle, entrò in greco come Iōánnēs e in latino come Iohannes, per poi diffondersi in tutta la cristianità. L’Europa occidentale mantenne la J/G iniziale (John, Jean, Juan, Giovanni); il mondo slavo orientale lo rimodellò in Ivan; e il Qurʼan conserva una forma araba parallela, Yaḥyā, per lo stesso profeta."},"mary":{"it":"Il nome della madre di Gesù e di Miriam, sorella di Mosè, e attraverso di loro uno dei nomi femminili più venerati al mondo. Il greco Maria e il latino Maria lo diffusero in ogni lingua cristiana; il Qurʼan riporta Maryam, l’unica donna in esso nominata, sicché il nome è altrettanto centrale nel mondo islamico."},"muhammad":{"it":"Il nome del Profeta dell’islam e, secondo molti conteggi, il nome maschile più diffuso sulla Terra. Dall’arabo muḥammad (radice ḥ-m-d, «lodare») viaggiò con l’islam in ogni lingua del mondo musulmano, ciascuna rimodellandone i suoni: turco Mehmet, persiano/urdu Mohammad, bosniaco Muhamed, ovest-africano Mamadou, sud-est asiatico Muhammad/Mohd."},"alexander":{"it":"Portato attraverso tre continenti da Alexander Magno, le cui conquiste piantarono il nome dalla Grecia all’India. In seguito il cristianesimo lo diffuse ancora di più attraverso santi e papi. Quasi ovunque si accorcia affettuosamente — Alex, Sasha, Sander, Xander, Ale, Iskandar — ed entrò persino nel mondo islamico come Iskandar/Sikandar."},"joseph":{"it":"Il nome del patriarca Joseph, venduto in Egitto, e di san Joseph, sposo di Mary. L’ebraico Yōsēf passò attraverso il greco Iōsḗph e il latino Ioseph in ogni lingua cristiana, contraendosi in José nella penisola iberica, Giuseppe in Italia e Josef nei mondi germanico e slavo. Il Qurʼan narra la storia dello stesso patriarca nella forma araba parallela Yūsuf, che si diffuse con l’islam dall’Africa occidentale all’Indonesia."},"michael":{"it":"In origine il nome dell’arcangelo Michael, condottiero guerriero delle schiere celesti, il cui culto portò il nome per tutta la cristianità. Il greco Michaḗl e il latino Michael si ramificarono in Michel, Miguel, Michele, Michael e nello slavo Mikhail, addolcendo lungo il cammino la gutturale ebraica ḵ in un suono k o h. Il Qurʼan chiama lo stesso angelo Mīkāʼīl, offrendo una forma islamica parallela in uso dall’Iran all’Africa occidentale."},"george":{"it":"Dal greco Geōrgios, costruito su geōrgós «contadino, lavoratore della terra», il nome deve la sua vastissima diffusione a Saint George, il martire uccisore di draghi venerato in tutta la cristianità e patrono di Inghilterra, Georgia ed Etiopia. Si dirama in Jorge, Giorgio, Georg e Jerzy, e il mondo slavo orientale lo ha scisso in due nomi vivi — il dotto Georgy e il quotidiano Yuri. Nel Caucaso è un beniamino nazionale: il georgiano Giorgi e l’armeno Gevorg."},"sophia":{"it":"Il greco sophía significa semplicemente «sapienza», personificata come virtù e consacrata nella grande chiesa di Hagia Sophia a Costantinopoli, «Santa Sapienza». Trasmesso dalla tradizione bizantina e ortodossa e portato da imperatrici e sante, si diffuse come Sofia, Sophie, Zsófia e Zofia. Oggi è uno dei nomi femminili più diffusi al mondo, in testa alle classifiche delle nascite in tutta Europa e nelle Americhe; il russo gli dà il tenero diminutivo Sonya."},"fatima":{"it":"Il nome di Fāṭima al-Zahrāʼ, figlia del Profeta Muhammad e moglie di ʿAlī, e dunque uno dei nomi femminili più onorati dell’islam — soprattutto nella tradizione sciita, in cui è la madre degli imam. Dalla radice araba f-ṭ-m («svezzare») si diffuse con l’islam e si addolcì lungo il cammino: il turco lo abbrevia in Fatma, il persiano ne arrotonda la desinenza in Fāṭeme, e l’Asia meridionale e sudorientale conservano la forma più piena Fatimah. Nei Balcani sopravvive come Fatima con il vezzeggiativo Fata."},"ali":{"it":"Il nome di ʿAlī ibn Abī Ṭālib, cugino e genero del Profeta Muhammad, quarto califfo nella tradizione sunnita e primo imam dell’islam sciita — il che fa di Ali uno dei nomi centrali del mondo musulmano, e anche uno dei «bei nomi», poiché al-ʿAlī è un attributo di Dio. Dall’arabo ʿAlī (radice ʿ-l-w, «essere alto») i suoni si trasmettono quasi immutati attraverso le lingue: turco e persiano Ali, urdu Ali, bosniaco Alija, ovest-africano Aliyu. In Occidente è noto soprattutto grazie al pugile Muhammad Ali."},"krishna":{"it":"Krishna è l’ottavo avatar di Vishnu e una delle divinità più amate dell’induismo — il mandriano suonatore di flauto di Vrindavan e il saggio auriga della Bhagavad Gita. Il sanscrito kṛṣṇa significa letteralmente \"scuro, nero\", a descrivere la sua carnagione, e ha generato forme affettuose come Kanha e il tamil Kannan. Come nome proprio è diffuso in tutta l’India e nell’intera diaspora indù; la sua diffusione nel Sud-est asiatico passa attraverso il teatro delle ombre wayang e il Mahabharata."},"rama":{"it":"Rama è un avatar di Vishnu e l’eroe del Ramayana, il re ideale di Ayodhya la cui vicenda è fra le più raccontate al mondo. Il sanscrito rāma significa \"piacevole, affascinante\". Fu soprattutto l’epopea a portare il nome in tutto il Sud-est asiatico: i re thailandesi della dinastia Chakri assumono tutti il nome regale di Rama, la stessa Ayutthaya prese nome da Ayodhya, luogo natale di Rama, e Rama sopravvive nel Reamker cambogiano (come Preah Ream), nel wayang giavanese e balinese e nel Phra Lak Phra Ram laotiano."},"david":{"it":"Il nome del re-pastore d’Israele, secondo re e uccisore di Golia, venerato tanto nell’ebraismo quanto nel cristianesimo e nell’islam. L’ebraico Dāwīḏ passò attraverso il greco e il latino in ogni lingua europea quasi immutato, mentre il georgiano Davit e l’etiope Dawit divennero nomi regali a pieno titolo. Poiché Davide è anche un profeta del Qurʼan, una linea islamica parallela corre attraverso l’arabo Dāwūd — Daud, Davut, Daudi — in tutto il mondo musulmano."},"daniel":{"it":"Dal profeta visionario del Libro di Daniele, la cui fede nella fossa dei leoni fece del nome un emblema di fermezza. L’ebraico Dāniyyēl passò attraverso il greco Daniḗl e il latino Daniel nell’Occidente cristiano, mantenendo una grafia straordinariamente stabile, mentre il mondo slavo lo rimodellò in Daniil e Danylo. Daniele è venerato anche nella tradizione islamica come il profeta Dāniyāl, la cui tomba a Susa resta luogo di pellegrinaggio."},"peter":{"it":"Il nome che Gesù diede al pescatore Simone — il greco Pétros, \"roccia\", traduzione del soprannome aramaico Kēfā — facendone la roccia su cui fu edificata la Chiesa. Primo papa, san Pietro portò il nome in ogni terra cristiana: latino Petrus, francese Pierre, spagnolo Pedro, italiano Pietro, russo Pyotr. I cristiani d’Oriente conservarono il greco Petros, e i cristiani di lingua araba dicono Buṭrus."},"paul":{"it":"Il cognomen romano Paulus, «piccolo», assunto dallʼapostolo Paul — nato Saul di Tarso — le cui lettere plasmarono la teologia cristiana e portarono il suo nome in tutto il mondo. Le Chiese di lingua greca lo conoscevano come Paûlos, e dal latino Paulus derivarono Pablo, Paolo, Paulo, Paweł e lo slavo Pavel. Lʼarmeno lo rimodellò in modo sorprendente in Poġos, e i cristiani di lingua araba lo chiamano Būlus."},"thomas":{"it":"Il soprannome dellʼapostolo che dubitò della Resurrezione finché non toccò le piaghe di Cristo — aramaico Tʼōmā, «gemello», che i Vangeli greci rendono anche come Dídymos. Attraverso il greco Thōmâs e il latino Thomas si diffuse in Occidente come Thomas, Tomás, Tommaso e Tomasz, mentre lʼoriente slavo lo rimodellò in Foma e Khoma. I cristiani di lingua araba conservano il suono aramaico come Tūmā."},"abraham":{"it":"Il patriarca venerato come padre dei credenti in tutte e tre le religioni abramitiche. L’ebraico Avraham, «padre di molte nazioni», passò attraverso il greco Abraám e il latino Abraham nell’Occidente cristiano, mentre il Qurʼan offre la forma parallela Ibrāhīm — uno dei nomi maschili più diffusi in tutto il mondo musulmano, dal Marocco all’Indonesia. Il neerlandese lo abbrevia in Bram; il Caucaso lo rimodella in Ibragim."},"isaac":{"it":"Il figlio di Abraham e secondo patriarca, il cui nome ebraico Yitzḥaq significa «egli ride». Il greco Isaák e il latino Isaac lo portarono a occidente — italiano Isacco, tedesco e russo Isaak —, mentre il Qurʼan chiama lo stesso profeta Isḥāq. Prediletto tanto dalle famiglie ebraiche quanto da quelle cristiane e musulmane, è stato portato da figure che vanno da Isaac Newton allo scrittore russo Isaak Babel."},"jacob":{"it":"Il terzo patriarca, poi ribattezzato Israele; il suo nome ebraico Yaʿaqov diede origine a uno degli alberi genealogici più intricati di tutta l’onomastica. Il latino Iacobus produsse Jacob, Jakob e lo slavo Yakov, ma una variante del latino volgare, Iacomus, si staccò dando l’italiano Giacomo, il francese Jacques, l’inglese James e gli iberici Diego, Santiago, Tiago e Jaime — tutti doppioni di un unico e medesimo nome. Il Qurʼan conserva il profeta come Yaʻqūb."},"moses":{"it":"Il profeta che guidò gli Israeliti fuori dall’Egitto; il suo nome ebraico Mosheh è tradizionalmente interpretato come «salvato dalle acque». Attraverso il greco Mōÿsês e il latino Moyses si diffuse come Moses, francese Moïse, spagnolo Moisés e italiano Mosè, mentre Mūsā — nominato nel Qurʼan più spesso di ogni altro profeta — divenne uno dei grandi nomi del mondo musulmano, portato dall’imperatore del Mali Mansa Musa."},"solomon":{"it":"Il re saggio, figlio di David; il suo nome ebraico Shlomoh deriva da shalom, «pace». Il greco Solomṓn e il latino Salomon diedero Solomon, il francese Salomon, l’italiano Salomone e il portoghese Salomão. Gli imperatori d’Etiopia rivendicarono la discendenza da lui nella dinastia salomonica, e il Qurʼan lo onora come il re-profeta Sulaymān — all’origine del turco Süleyman, portato dal più grande dei sultani ottomani."},"matthew":{"it":"Il nome dellʼapostolo ed evangelista Matthew, il pubblicano chiamato da Gesù e tradizionale autore del primo Vangelo. Lʼebraico Mattityāhū («dono di Yahweh») fu abbreviato in greco in Maththaîos e latinizzato in Matthaeus, per poi diffondersi in tutta la cristianità come Matteo, Mateo, Matthieu, Mateusz e lo slavo Matvei. I cristiani di lingua araba conoscono lʼevangelista come Mattā."},"adam":{"it":"Il nome del primo uomo, plasmato dalla terra nella Genesi e nominato venticinque volte nel Qurʼan, e perciò condiviso da ebrei, cristiani e musulmani. Cosa insolita, non richiede quasi alcuna trasformazione da una lingua all’altra — Adam in inglese, tedesco, polacco e arabo, Adán in spagnolo, Adamo in italiano, Adem in turco e bosniaco, Adamu in hausa e swahili. Nel mondo islamico Ādam è molto comune come nome di tutti i giorni."},"noah":{"it":"Il costruttore dell’arca che sopravvisse al Diluvio, onorato tanto nella Bibbia quanto nel Qurʼan. L’ebraico Nōaḥ passò attraverso il greco Nôe e il latino Noe per dare il romanzo Noé e l’italiano Noè, mentre l’inglese conservò la forma più piena Noah. Nel ventunesimo secolo Noah è balzato in cima alle classifiche dei nomi maschili negli Stati Uniti e in tutta Europa, ed è stato persino ripreso in prestito in Giappone come il nome moderno Noa. Il Qurʼan narra la stessa storia nella forma araba parallela Nūḥ, uno dei cinque massimi profeti dell’islam."},"gabriel":{"it":"Il nome dellʼarcangelo che rivela visioni a Daniel, annuncia la nascita di John e di Jesus e che nellʼislam detta il Qurʼan a Muhammad. Lʼebraico Gaḇrīʼēl divenne il greco Gabriḗl e il latino Gabriel, restando vicino alla sua fonte in francese, spagnolo, portoghese e tedesco, addolcendosi nellʼitaliano Gabriele e nello slavo Gavriil / Gavrilo. Il Qurʼan chiama lo stesso angelo Jibrīl, e in Etiopia lʼarcangelo Gabrʼel è profondamente venerato."},"elijah":{"it":"Il nome dellʼardente profeta del IX secolo a.C. che affrontò i sacerdoti di Baal sul monte Carmel e fu assunto in cielo in un turbine. Nel greco del Nuovo Testamento è Ēlías, che diede il latino Elias e le numerose forme europee Elias / Élie / Ilie, mentre il mondo slavo orientale ne fece il quotidiano Ilya. La forma più piena Elijah è diventata uno dei nomi inglesi moderni di maggior successo. Il Qurʼan onora lo stesso profeta con la forma araba parallela Ilyās."},"sarah":{"it":"Il nome della moglie del patriarca Abraham, che nella Genesi viene rinominata da Sarai in Sarah, « principessa ». Il greco Sárra e il latino Sara lo portarono attraverso il mondo cristiano, dove divenne uno dei nomi femminili più popolari dellʼepoca moderna. Poiché Abraham è un patriarca comune, lo stesso nome sopravvive nel mondo musulmano come Sāra, e varia affettuosamente da Zara al finlandese Saara."},"anna":{"it":"Dallʼebraico Ḥannāh, la madre del profeta Samuel — un nome che significa « grazia ». Il greco lo rese Ánna — portato nel Vangelo di Luca dalla profetessa Anna — e attraverso il latino divenne uno dei nomi femminili più diffusi dʼEuropa, onorato inoltre come nome di santʼAnne, madre della Vergine Mary. Lʼinglese conserva sia Anna, di origine greca, sia Hannah, ripristinato dallʼebraico, come un doppione, e la stessa figura compare nellʼislam come Ḥanna, la madre di Mary."},"elizabeth":{"it":"Dallʼebraico Elišévaʿ, la moglie di Aaron e, nel Vangelo di Luca, la madre di John il Battista. Il greco Elisábet e il latino Elisabeth lo diffusero per la cristianità, dove fu portato da santi e da una lunga schiera di regine, soprattutto Elizabeth I ed Elizabeth II dʼInghilterra. Nella penisola iberica lo stesso nome fu rimodellato in un celebre ramo derivato, Isabel (italiano Isabella), mentre il mondo slavo e quello ungherese gli diedero Yelizaveta ed Erzsébet."},"omar":{"it":"Portato da ʿUmar ibn al-Khattāb, compagno del Profeta e secondo califfo rāshidūn il cui regno plasmò il primo Stato islamico, ʿUmar è uno dei classici nomi maschili del mondo musulmano. Dalla radice araba ʿ-m-r (“vivere, prosperare”) significa “longevo, fiorente”. Si è trasformato nel turco Ömer e nel bosniaco Omer, ed è giunto in Occidente grazie a personaggi come Omar Sharif. Un nome ebraico non correlato, Omar — un nipote di Esaù nella Genesi — è soltanto una distinta coincidenza sonora."},"aisha":{"it":"Il nome di ʿĀʼisha bint Abī Bakr, moglie del Profeta Muhammad celebre come studiosa e narratrice di hadith, il che ne ha fatto uno dei nomi femminili più diffusi in tutto il mondo musulmano. Dalla radice araba ʿ-y-sh (“vivere”) significa “vivente, in vita”. Il turco lo ha trasformato in Ayşe — a lungo il nome femminile più comune in Turchia —, mentre nel Maghreb si usa Aïcha e in Asia meridionale Ayesha. Negli ultimi decenni si è affermato ampiamente anche in Gran Bretagna, Francia e Stati Uniti."},"khadija":{"it":"Khadīja bint Khuwaylid fu la prima moglie del Profeta Muhammad, una ricca mercante della Mecca e la prima persona ad abbracciare lʼislam; da allora il suo nome è tenuto in gran conto. Deriva dalla radice araba kh-d-j, associata a un bambino “nato presto” o prematuro. Il turco lo porta come Hatice, lʼAfrica occidentale come lʼhausa Hadiza e il senegalese Khady, e lo swahili come Hadija. Insieme a Fatima e Aisha figura tra i nomi femminili più comuni del mondo musulmano."},"abdullah":{"it":"Un nome teoforico che significa “servo di Dio”, formato da ʿabd (“servo”) e Allāh. Fu il nome del padre del Profeta Muhammad, ʿAbd Allāh ibn ʿAbd al-Muttalib, e un hadith indica ʿAbdullāh e ʿAbd al-Rahmān come i nomi più amati da Dio — perciò è tra i nomi più raccomandati nellʼislam. Percorre il mondo musulmano con lievi mutamenti fonetici: il persiano Abdollah, il maghrebino Abdallah e Abdellah, il nigeriano Abdullahi, lʼovest-africano francofono Abdoulaye e il bosniaco Abdulah."},"hassan":{"it":"Ḥasan (radice ḥ-s-n, “essere buono, bello”) era il nome di Hasan ibn Ali, nipote maggiore del Profeta Muhammad e secondo imam sciita. È quasi sempre abbinato al nome del fratello minore — Hasan e Husayn insieme. Portato dallʼislam in tutto il mondo, ha mantenuto una forma notevolmente stabile (turco Hasan, bosniaco Hasan/Haso) e resta uno dei nomi maschili più comuni del mondo musulmano."},"husayn":{"it":"Ḥusayn è il diminutivo di Ḥasan — « piccolo Hasan », « il piccolo bello ». Fu portato da Husayn ibn Ali, nipote minore del Profeta, il cui martirio nella battaglia di Kerbala nel 680 d.C. fece di questo nome il cuore emotivo dell’islam sciita, commemorato ogni anno durante l’Ashura. Le sue forme percorrono il mondo musulmano: il persiano Hossein, il turco Hüseyin, il Hussain sud-asiatico e il Hussein arabo portato da Saddam Hussein e dal re Hussein di Giordania."},"zaynab":{"it":"Zaynab è il nome di una pianta del deserto profumata e fiorita. Fu portato da una figlia del Profeta Muhammad, Zaynab bint Muhammad, e dalla nipote Zaynab bint Ali, sorella di Husayn ed eroina venerata della tragedia di Kerbala. Il nome prospera in tutto il mondo musulmano, soprattutto come il turco Zeynep — per anni il nome femminile più popolare della Turchia — e come l’africano-occidentale Zenabou."},"nicholas":{"it":"Dal greco Nikólaos, « vittoria del popolo », diffuso in tutta la cristianità dal culto di san Nicholas di Myra — il vescovo del IV secolo la cui leggenda dei doni divenne Santa Claus, nome a sua volta logoratosi dal neerlandese Sinterklaas. Quasi ovunque si accorcia affettuosamente: Klaus in tedesco, Klaas in neerlandese, Nikos in greco, Kolya in russo. L’Europa orientale lo rimodellò in Nikolai, Mykola e Mikuláš, mentre l’Ungheria ne fece Miklós."},"helen":{"it":"La forma inglese del greco Helénē, probabilmente da una parola che significa « torcia » o « la splendente ». Portata da Helen di Troia, la cui bellezza avrebbe « fatto salpare mille navi », e da sant’Helena, madre dell’imperatore Constantine, a cui si attribuisce il ritrovamento della Vera Croce. Attraverso il latino Helena divenne Elena nei mondi romanzo e slavo meridionale e Yelena / Olena a oriente, mentre l’ungherese la rimodellò in Ilona."},"catherine":{"it":"Dal greco Aikaterínē, presto collegato per etimologia popolare a katharós, « puro », il che fissò la grafia con -th- in Occidente. Diffuso dal culto assai popolare di santa Catherine di Alessandria, divenne uno dei nomi femminili più usati d’Europa, portato da regine e imperatrici, da Catherine de Medici a Catherine the Great. Si accorcia in tutto un guardaroba di vezzeggiativi — Kate, Katie, Katya, Kasia — uno dei quali, il Karin tedesco e svedese, è omofono di un nome di bambina giapponese."},"margaret":{"it":"Dal greco margarítēs (\"perla\"), parola che il greco stesso aveva preso in prestito da un Oriente più lontano. Il culto di santa Margherita di Antiochia lo rese amatissimo in tutta lʼEuropa medievale, portato poi da regine e da figure che vanno da Margaret Thatcher a Margaret Atwood. I suoi vezzeggiativi hanno preso vita propria — il tedesco Greta, lʼitaliano e spagnolo Rita, e lʼinglese Daisy, poiché il francese marguerite finì per indicare il fiore."},"philip":{"it":"Dal greco Phílippos (\"amante dei cavalli\"), nome della casa reale macedone portato da Philip II, padre di Alessandro Magno. Come nome di un apostolo si diffuse in tutta la cristianità e divenne caro ai re iberici — sei Felipe spagnoli e diversi Filipe portoghesi, da cui prendono nome le Filippine. Ai britannici è noto soprattutto attraverso Prince Philip, il compianto duca di Edimburgo."},"theodore":{"it":"Dal greco Theódōros (\"dono di Dio\"), immagine speculare di Dorotea. Portato da molti santi delle origini, mise radici in tutta lʼEuropa e oltre — il russo Fyodor di Dostoevskij e lʼetiope Tewodros. In inglese incanta attraverso i suoi diminutivi Ted, Teddy e Theo."},"anthony":{"it":"Dal nome gentilizio romano Antōnius, unʼantica gens forse di origine etrusca il cui membro più famigerato fu Mark Antony (Marcus Antōnius). I molti santi di nome Anthony — soprattutto Antonio il Grande e Antonio di Padova — lo portarono per la cristianità, dove Antonio divenne uno dei nomi più comuni dʼItalia e della penisola iberica. La grafia con la h riflette un successivo, erroneo collegamento al greco ánthos (\"fiore\")."},"julia":{"it":"Il femminile del nome gentilizio romano Iūlius, la famiglia di Giulio Cesare e dellʼimperatore Augusto, che fece di Iūlia uno dei grandi nomi della dinastia giulio-claudia — sia la figlia di Cesare sia la figlia di Augusto si chiamavano Julia. A lungo anche nome di una santa cristiana, è oggi uno dei nomi femminili più diffusi in Europa e nelle Americhe. Il suo corrispettivo maschile sopravvive come Julius, Julio e Jules."},"lakshmi":{"it":"Lakshmi è la dea indù della ricchezza, della fortuna e della bellezza, nonché la consorte di Vishnu, di cui assume una forma corrispondente accanto a ciascuno dei suoi avatar. Il sanscrito lakṣmī deriva da lakṣ «segnare, percepire», da cui il senso di un segno di buon auspicio e, per estensione, di prosperità. È venerata soprattutto durante il Diwali, e il suo nome è uno dei nomi femminili più diffusi in tutta lʼIndia meridionale — anche se composti come Lakshmi Narayan e cognomi come Mittal lo portano pure per gli uomini. Nel Bengala la dea e il nome si pronunciano Lokkhi."},"arjun":{"it":"Arjuna è lʼeroe-arciere del Mahabharata — il terzo dei cinque fratelli Pandava, figlio del dio Indra, e il guerriero al quale Krishna consegna la Bhagavad Gita sul campo di battaglia di Kurukshetra. Il sanscrito arjuna significa «luminoso, argenteo, bianco». Nella forma Arjun è uno dei nomi maschili più diffusi nellʼIndia odierna, e lʼepopea ha portato la figura fino al Sud-est asiatico, dove il raffinato ksatriya Arjuna (in giavanese Janaka) è un beniamino del teatro delle ombre wayang."},"sita":{"it":"Sita è lʼeroina del Ramayana e la sposa di Rama, un avatar di Lakshmi e lʼideale stesso della virtù, della devozione e della costanza. Il suo nome sanscrito significa «solco»: fu trovata dal re Janaka in un campo arato, figlia della dea della terra Bhumi. Lʼepopea la diffuse in tutto il Sud-est asiatico — è Nang Sida (นางสีดา) nel Ramakien thailandese, Sinta o Shinta nel wayang giavanese e Neang Seda nel Reamker cambogiano."},"ganesh":{"it":"Ganesha è il figlio dalla testa d’elefante di Shiva e Parvati, l’amato dio che rimuove gli ostacoli e patrono degli inizi, del sapere e delle arti, invocato prima di ogni nuova impresa. Il suo nome sanscrito unisce gaṇa «schiere, truppe» a īśa «signore», ed è noto anche come Vinayaka e Ganapati. Nella forma Ganesh è un diffuso nome maschile indiano, e la divinità si diffuse in tutto il Sud-est asiatico — venerata in Thailandia come Phra Phikhanet (พระพิฆเนศ), patrono delle arti, e in Indonesia come Ganesha, la cui immagine è l’emblema dell’Istituto di Tecnologia di Bandung (ITB)."},"priya":{"it":"Priya non è un nome di divinità, ma un nome proprio a tutti gli effetti — il femminile del sanscrito priya «amato, caro», dalla radice prī «piacere, compiacere». È uno dei nomi femminili più diffusi oggi in tutta lʼIndia, in Nepal, in Bangladesh e in Sri Lanka, e raggiunge senza difficoltà la diaspora come forma simpatica e facile da pronunciare. In tamil il maschile Priyan o Priya si usa anche per gli uomini. La radice è antica: è imparentata con il nome della dea germanica Frigg, entrambi dallʼindoeuropeo *priH- «amato»."}};
